import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Bento Grids — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"bento-grids-01-overview-and-concepts.md","filePath":"bento-grids-01-overview-and-concepts.md"}'),n={name:"bento-grids-01-overview-and-concepts.md"};function s(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="bento-grids-—-overview-concepts" tabindex="-1">Bento Grids — Overview &amp; Concepts <a class="header-anchor" href="#bento-grids-—-overview-concepts" aria-label="Permalink to &quot;Bento Grids — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-a-bento-grid" tabindex="-1">What Is a Bento Grid? <a class="header-anchor" href="#what-is-a-bento-grid" aria-label="Permalink to &quot;What Is a Bento Grid?&quot;">​</a></h2><p>A Bento Grid is a visual release summary — a polished, at-a-glance layout that turns release notes into something you&#39;d actually want to share with a customer-facing team, a sales team, or leadership.</p><p>The name comes from bento boxes: every compartment serves a purpose. Each cell in the grid highlights a shipped feature, improvement, or fix in a compact, structured format. The result is something that communicates what went out without requiring anyone to parse a wall of bullet points.</p><hr><h2 id="the-problem-it-solves" tabindex="-1">The Problem It Solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The Problem It Solves&quot;">​</a></h2><p>Release notes are useful internally but rarely effective as communication artifacts. By the time they reach sales, CS, or leadership, they&#39;ve been paraphrased into an email, stripped of context, or ignored entirely.</p><p>Bento Grids give release notes a visual form that travels well — a self-contained snapshot of what shipped, designed to be read in seconds and easy to share externally.</p><hr><h2 id="how-bento-grids-work" tabindex="-1">How Bento Grids Work <a class="header-anchor" href="#how-bento-grids-work" aria-label="Permalink to &quot;How Bento Grids Work&quot;">​</a></h2><p>A Bento Grid takes source content — either a set of Release Notes from an existing Release, or a file you upload — and uses AI to group it into sections. Each section becomes a cell in the grid. You review and approve the grouping, then export or save the result.</p><p>The process has four steps:</p><ol><li><strong>Source</strong> — select a Release Note from an existing Release, or upload a file with release content</li><li><strong>Configure</strong> — choose your appearance settings (aspect ratio, theme, layout)</li><li><strong>Review</strong> — the AI groups the content into cells; you review and can adjust before confirming</li><li><strong>Export or save</strong> — download as PNG or PowerPoint, upload to Google Slides, or save the grid to return to later</li></ol><hr><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><h3 id="release-note-linked-bento-grids" tabindex="-1">Release Note-linked Bento Grids <a class="header-anchor" href="#release-note-linked-bento-grids" aria-label="Permalink to &quot;Release Note-linked Bento Grids&quot;">​</a></h3><p>When you create a Bento Grid from an existing Release Note, it is linked to that note. These grids appear in the Bento Grids list alongside the name of the Release they came from. If you already have a saved grid for a given Release Note, returning to it opens the saved version.</p><h3 id="standalone-bento-grids" tabindex="-1">Standalone Bento Grids <a class="header-anchor" href="#standalone-bento-grids" aria-label="Permalink to &quot;Standalone Bento Grids&quot;">​</a></h3><p>If you upload a file (rather than selecting a Release Note), the resulting grid is standalone — it is not linked to any Release. Standalone grids still appear in the Bento Grids list but are labeled as file-sourced.</p><h3 id="appearance-configuration" tabindex="-1">Appearance Configuration <a class="header-anchor" href="#appearance-configuration" aria-label="Permalink to &quot;Appearance Configuration&quot;">​</a></h3><p>When you create or regenerate a Bento Grid, you choose:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Options</th><th>Effect</th></tr></thead><tbody><tr><td>Aspect ratio</td><td>1:1, 4:3, 16:9</td><td>Controls the grid&#39;s proportions — 16:9 works well for slides, 1:1 for social media</td></tr><tr><td>Output type</td><td>Single image, Presentation</td><td>Single produces one full grid; Presentation produces one slide per cell</td></tr><tr><td>Theme</td><td>Light, Dark</td><td>Controls the colour scheme of the exported grid</td></tr><tr><td>Tags</td><td>On / Off</td><td>Whether each cell includes a category tag</td></tr><tr><td>Icons</td><td>On / Off</td><td>Whether each cell includes an icon</td></tr></tbody></table><h3 id="ai-grouping" tabindex="-1">AI Grouping <a class="header-anchor" href="#ai-grouping" aria-label="Permalink to &quot;AI Grouping&quot;">​</a></h3><p>The AI reads the source content and groups related items into distinct cells. You review this grouping before it is finalized — you are not locked into the AI&#39;s interpretation. The grouping step is a starting point, not the final output.</p><hr><h2 id="how-bento-grids-relate-to-the-rest-of-lodestone" tabindex="-1">How Bento Grids Relate to the Rest of Lodestone <a class="header-anchor" href="#how-bento-grids-relate-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Bento Grids Relate to the Rest of Lodestone&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Object</th><th>Relationship</th></tr></thead><tbody><tr><td>Releases</td><td>The most common source for Bento Grids. A Release Note generated from a Release becomes the content input for the grid.</td></tr><tr><td>Release Notes</td><td>Each Bento Grid is either linked to a Release Note or standalone. The Bento Grids list shows all Release Notes for which a grid has been saved.</td></tr><tr><td>Exports</td><td>Bento Grids export as PNG, PowerPoint, or can be uploaded directly to Google Slides.</td></tr></tbody></table><hr><h2 id="who-can-use-bento-grids" tabindex="-1">Who Can Use Bento Grids <a class="header-anchor" href="#who-can-use-bento-grids" aria-label="Permalink to &quot;Who Can Use Bento Grids&quot;">​</a></h2><p>Any workspace member — both Admins and Builders — can create and export Bento Grids. Access requires the same permission as the Releases module.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating, configuring, and exporting Bento Grids.</em></p>',34)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
